import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int stock = sc.nextInt();
        int requested = sc.nextInt();
        try {
            placeOrder(stock, requested);
        } catch (OutOfStockException e) {
            System.out.println("Order failed: " + e.getMessage());
        }
    }

    static void placeOrder(int stock, int requested) {
        if (requested > stock) {
            throw new OutOfStockException("Only " + stock + " left in stock");
        }
        System.out.println("Order confirmed: " + requested + " units");
    }
}

class OutOfStockException extends RuntimeException {
    OutOfStockException(String message) {
        super(message);
    }
}
